BEGIN;
DO $test$
DECLARE ids uuid[];a uuid;b uuid;owner_id uuid;m uuid:=gen_random_uuid();scheduled uuid:=gen_random_uuid();tid text:='__pause_'||gen_random_uuid()::text;sid uuid;j jsonb;req uuid;logo text:='https://res.cloudinary.com/demo/image/upload/v1/fixture.png';
BEGIN
 SELECT array_agg(id) INTO ids FROM(SELECT id FROM public.profiles p WHERE NOT coalesce(banned,false) AND NOT EXISTS(SELECT 1 FROM public.squad_members WHERE user_id=p.id) AND NOT EXISTS(SELECT 1 FROM public.admins WHERE user_id=p.id) ORDER BY id LIMIT 2)q;
 a:=ids[1];b:=ids[2];SELECT user_id INTO owner_id FROM public.admins LIMIT 1;ASSERT a IS NOT NULL AND b IS NOT NULL AND owner_id IS NOT NULL,'Fixtures';
 INSERT INTO public.tournaments(id,name,status,reg_open,slots,entry_cost_ap) VALUES(tid,'ROLLBACK PAUSE','upcoming',true,4,0);
 INSERT INTO public.matches(id,tournament_id,title,status) VALUES(m,tid,'ROLLBACK LIVE','live'),(scheduled,tid,'ROLLBACK SCHEDULED','scheduled');
 PERFORM set_config('request.jwt.claim.sub','',true);ASSERT public.xr_pause_request(m)->>'error'='unauthorized','Anon denied';ASSERT public.xr_squad_custom_logo_set(gen_random_uuid(),logo)->>'error'='unauthorized','Logo anon denied';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 ASSERT public.xr_pause_request(gen_random_uuid())->>'error'='match_not_found','Missing match';
 ASSERT public.xr_pause_request(scheduled)->>'error'='match_not_live','Scheduled refused';
 ASSERT public.xr_pause_request(m)->>'error'='not_registered','Nonparticipant refused';
 INSERT INTO public.registrations(id,tournament_id,squad,captain,uid,ign,phone,status,user_id) VALUES('__pause_reg_'||m,tid,'Test Squad','Test Captain','10000001','Test IGN','+910000000001','pending',a);
 j:=public.xr_pause_request(m);ASSERT (j->>'ok')::boolean,j::text;req:=(j->>'request_id')::uuid;
 ASSERT j->>'status'='pending' AND NOT (j->>'game_paused')::boolean,'Request never claims game paused';
 ASSERT (j->>'expires_at')::timestamptz-(j->>'created_at')::timestamptz BETWEEN interval '119 seconds' AND interval '121 seconds','Two minutes';
 ASSERT (public.xr_pause_request(m)->>'already_requested')::boolean,'Retry idempotent';ASSERT(SELECT count(*) FROM public.xr_match_pause_requests WHERE match_id=m)=1,'One per player/match';
 UPDATE public.xr_match_pause_requests SET expires_at=now()-interval '1 second' WHERE id=req;
 ASSERT public.xr_pause_request(m)->>'status'='expired','Expired status';ASSERT(SELECT count(*) FROM public.xr_match_pause_requests WHERE match_id=m)=1,'No repeat after expiry';
 ASSERT public.xr_pause_request_list(m)->>'error'='forbidden','Player cannot list';
 PERFORM set_config('request.jwt.claim.sub',b::text,true);ASSERT public.xr_pause_request_list(m)->>'error'='forbidden','Other cannot list';
 INSERT INTO public.xr_feed_hosts(user_id) VALUES(b) ON CONFLICT DO NOTHING;
 ASSERT public.xr_pause_request_list(m)->>'error'='forbidden','Feed power not reused';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);j:=public.xr_pause_request_list(m);ASSERT (j->>'ok')::boolean AND jsonb_array_length(j->'requests')=1,'Admin list';ASSERT j->'requests'->0->>'status'='expired','Admin expiry';
 ASSERT j::text NOT LIKE '%phone%' AND j::text NOT LIKE '%uid%' AND j::text NOT LIKE '%device%','No private identifiers';
 UPDATE public.matches SET status='done' WHERE id=m;
 ASSERT public.xr_pause_request_list(m)->'requests'->0->>'status'='match_closed','Closed status';
 PERFORM set_config('request.jwt.claim.sub',a::text,true);ASSERT public.xr_pause_request(m)->>'status'='match_closed','Retry after close';
 INSERT INTO public.squad_creators(user_id) VALUES(a) ON CONFLICT DO NOTHING;
 j:=public.create_squad('__Logo Fixture '||substr(m::text,1,8),'TEST',NULL);ASSERT(j->>'ok')::boolean,j::text;sid:=(j->>'id')::uuid;
 ASSERT public.xr_squad_custom_logo_set(sid,NULL)->>'error'='invalid_logo_url','Null URL';
 ASSERT public.xr_squad_custom_logo_set(sid,'https://res.cloudinary.com.evil.test/demo/image/upload/a.png')->>'error'='invalid_logo_url','Lookalike host';
 ASSERT public.xr_squad_custom_logo_set(sid,'https://res.cloudinary.com/demo/video/upload/a.mp4')->>'error'='invalid_logo_url','Video rejected';
 ASSERT public.xr_squad_custom_logo_set(sid,'https://res.cloudinary.com/demo/image/upload/../bad.png')->>'error'='invalid_logo_url','Traversal rejected';
 ASSERT public.xr_squad_custom_logo_set(sid,'https://res.cloudinary.com/demo/image/upload/a.png?token=secret')->>'error'='invalid_logo_url','Query secrets rejected';
 j:=public.xr_squad_custom_logo_set(sid,logo);ASSERT(j->>'ok')::boolean,j::text;ASSERT(SELECT logo_url FROM public.squads WHERE id=sid)=logo,'Captain logo set';
 PERFORM set_config('request.jwt.claim.sub',b::text,true);ASSERT public.xr_squad_custom_logo_set(sid,logo)->>'error'='not_found_or_not_captain','Noncaptain denied';
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);UPDATE public.profiles SET banned=true WHERE id=a;PERFORM set_config('request.jwt.claim.sub',a::text,true);
 ASSERT public.xr_squad_custom_logo_set(sid,logo)->>'error'='account_restricted','Restricted captain denied';ASSERT public.xr_pause_request(m)->>'error'='account_restricted','Restricted player denied';
END $test$;
SET LOCAL ROLE anon;
DO $grants$ BEGIN ASSERT NOT has_table_privilege(current_user,'public.xr_match_pause_requests','SELECT'),'Pause direct denied';ASSERT NOT has_function_privilege(current_user,'public.xr_pause_request(uuid)','EXECUTE'),'Anon execute denied';END $grants$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $grants$ BEGIN ASSERT NOT has_table_privilege(current_user,'public.xr_match_pause_requests','SELECT'),'Requests via admin RPC only';ASSERT has_function_privilege(current_user,'public.xr_pause_request(uuid)','EXECUTE'),'Auth execute';END $grants$;
RESET ROLE;

ROLLBACK;